'use strict';
(()=>{
 const observed=document.querySelectorAll('.why-card');
 if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('is-visible',e.isIntersecting)),{threshold:.12});observed.forEach(e=>observer.observe(e));}
 const search=document.querySelector('#feature-search');
 if(search){const cards=[...document.querySelectorAll('.catalog-feature')],sections=[...document.querySelectorAll('.feature-catalog-section')];search.addEventListener('input',()=>{const query=search.value.trim().toLowerCase();let count=0;cards.forEach(card=>{card.hidden=!card.dataset.featureSearch.toLowerCase().includes(query);if(!card.hidden)count++;});sections.forEach(section=>section.hidden=![...section.querySelectorAll('.catalog-feature')].some(c=>!c.hidden));document.querySelector('#feature-count').textContent=`${count} feature${count===1?'':'s'} ${query?'found':'to explore'}`;document.querySelector('#feature-empty').hidden=count>0;});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable){e.preventDefault();search.focus();}});}
 const days=document.querySelector('#reservation-days');if(!days)return;
 const hero=document.querySelector('#hero'),now=new Date();let year=now.getFullYear(),month=now.getMonth(),day=now.getDate(),time='09:30',kind='Kayak';
 const data={Kayak:{title:'Kayak Booking',sub:'Your next outdoor adventure',image:'kayak.webp',color:'#4655f5',wash:'#eaf0ff',duration:'30 min'},'Wine Tasting':{title:'Wine Tasting',sub:'A moment worth savoring',image:'tastings.webp',color:'#965048',wash:'#f8eeeb',duration:'60 min'},Hairdresser:{title:'Your next haircut',sub:'A little time for you',image:'beauty.webp',color:'#977047',wash:'#f7f0e7',duration:'45 min'},'Car Rentals':{title:'Your next adventure',sub:'Pick a time. Hit the road.',image:'rentals.webp',color:'#277a63',wash:'#eaf7f0',duration:'Pickup'}};
 const chosenDate=()=>new Date(year,month,day,12);
 function selection(){const date=chosenDate();document.querySelector('#reservation-chosen-date').textContent=date.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});document.querySelector('#reservation-selection').textContent=`Selected: ${date.toLocaleDateString('en-US',{month:'short',day:'numeric'})} · ${time}`;}
 function render(){const count=new Date(year,month+1,0).getDate();day=Math.min(day,count);days.replaceChildren();document.querySelector('#reservation-month-label').textContent=new Date(year,month,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});const start=(new Date(year,month,1).getDay()+6)%7;for(let i=0;i<start;i++){const blank=document.createElement('span');blank.setAttribute('aria-hidden','true');days.append(blank);}for(let n=1;n<=count;n++){const b=document.createElement('button');b.type='button';b.textContent=n;b.setAttribute('aria-label',new Date(year,month,n,12).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}));b.setAttribute('aria-pressed',String(n===day));b.addEventListener('click',()=>{day=n;render();});days.append(b);}selection();}
 document.querySelector('#month-prev').addEventListener('click',()=>{if(--month<0){month=11;year--;}render();});document.querySelector('#month-next').addEventListener('click',()=>{if(++month>11){month=0;year++;}render();});
 const slots=document.querySelector('#reservation-slots');['09:30','11:30','13:30','15:30','17:30'].forEach(value=>{const button=document.createElement('button');button.type='button';button.textContent=value;button.setAttribute('aria-pressed',String(value===time));button.addEventListener('click',()=>{time=value;slots.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));selection();});slots.append(button);});
 const tabs=[...document.querySelectorAll('[data-demo-kind]')];tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>{kind=tab.dataset.demoKind;const d=data[kind];tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===tab));b.tabIndex=b===tab?0:-1;});hero.style.setProperty('--demo-accent',d.color);hero.style.setProperty('--demo-wash',d.wash);document.querySelector('#reservation-title').textContent=d.title;document.querySelector('#reservation-subtitle').textContent=d.sub;document.querySelector('#reservation-duration').textContent=d.duration;const photo=document.querySelector('#reservation-photo');photo.src='/assets/usecases/'+d.image;photo.alt=kind+' booking example';});tab.tabIndex=index===0?0:-1;tab.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].click();tabs[next].focus();});});render();
})();
